package me.pikanote.companion;
import android.app.*;import android.content.*;import android.net.Uri;import android.database.Cursor;import android.provider.OpenableColumns;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;
final class MemorySharingChecks{
 static void yes(boolean b,String m)throws Exception{if(!b)throw new Exception(m);}
 static void run(Instrumentation i)throws Exception{Context c=i.getTargetContext();File boxDir=new File(c.getFilesDir(),"memory-sharing-check");Context box=new ContextWrapper(c){public File getFilesDir(){boxDir.mkdirs();return boxDir;}};Store store=new Store(box);ArrayList<File> exported=new ArrayList<>();try{String full="Полная расшифровка. English words.\n".repeat(120);JSONObject snap=store.snapshot(),row=new JSONObject().put("id","m7").put("text","Preview").put("truncated",true).put("wav",true).put("title","Fixture");snap.getJSONArray("memories").put(row);store.state.put("snapshot",snap);Files.write(store.safeFile("note_007.txt").toPath(),full.getBytes(StandardCharsets.UTF_8));byte[] audio=new byte[80];System.arraycopy("RIFF".getBytes(StandardCharsets.US_ASCII),0,audio,0,4);Files.write(store.safeFile("note_007.wav").toPath(),audio);yes(MemorySharing.transcript(store,row).equals(full),"Preview shared instead of full transcript");Intent share=MemorySharing.prepare(c,store,"m7");yes(Intent.ACTION_SEND_MULTIPLE.equals(share.getAction()),"Missing two-file share");ArrayList<Uri> streams=share.getParcelableArrayListExtra(Intent.EXTRA_STREAM);yes(streams.size()==2&&share.getClipData().getItemCount()==2,"Missing attachments/ClipData");exported.add(new File(new File(c.getCacheDir(),"memory-shares"),streams.get(0).getPathSegments().get(0)));yes((share.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&(share.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0,"Incorrect URI grants");yes(full.equals(share.getStringExtra(Intent.EXTRA_TEXT)),"Incorrect share text");try(InputStream in=c.getContentResolver().openInputStream(streams.get(0))){yes(full.equals(new String(in.readAllBytes(),StandardCharsets.UTF_8)),"TXT bytes incorrect");}try(InputStream in=c.getContentResolver().openInputStream(streams.get(1))){yes(Arrays.equals(audio,in.readAllBytes()),"WAV bytes incorrect");}yes("audio/wav".equals(c.getContentResolver().getType(streams.get(1))),"WAV MIME missing");try(Cursor cursor=c.getContentResolver().query(streams.get(1),null,null,null,null)){yes(cursor.moveToFirst()&&cursor.getLong(cursor.getColumnIndexOrThrow(OpenableColumns.SIZE))==audio.length,"Openable attachment metadata missing");}boolean denied=false;try{c.getContentResolver().openFileDescriptor(streams.get(0),"w");}catch(FileNotFoundException expected){denied=true;}yes(denied,"Receiver can overwrite shared file");denied=false;try{c.getContentResolver().openInputStream(Uri.parse("content://"+c.getPackageName()+".memory-share/../phone-store.aes"));}catch(Exception expected){denied=true;}yes(denied,"Provider exposed private files");row.put("archived",true);Intent textOnly=MemorySharing.prepare(c,store,"m7");Uri textUri=textOnly.getParcelableExtra(Intent.EXTRA_STREAM);exported.add(new File(new File(c.getCacheDir(),"memory-shares"),textUri.getPathSegments().get(0)));yes(Intent.ACTION_SEND.equals(textOnly.getAction())&&"text/plain".equals(textOnly.getType())&&textOnly.getClipData().getItemCount()==1,"Archived memory leaked stale WAV");row.put("truncated",false).put("text","Edited unsynchronized transcript");yes(MemorySharing.transcript(store,row).equals("Edited unsynchronized transcript"),"Copy ignored current phone edit");}finally{for(File f:exported)PhoneBackup.remove(f);PhoneBackup.remove(boxDir);}}
}
